#include <cuda_runtime.h>

#define BLOCK_SIZE 16

__global__ void matrix_multiply_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; tile++) {
        int tile_col = tile * BLOCK_SIZE + threadIdx.x;
        int tile_row = tile * BLOCK_SIZE + threadIdx.y;

        // Load tile of A into shared memory
        if (row < N && tile_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + tile_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        if (tile_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tile_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        for (int k = 0; k < BLOCK_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
