#include <cuda_runtime.h>

#define BLOCK_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matrix_multiply_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int num_tiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int tile = 0; tile < num_tiles; tile += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int unroll = 0; unroll < UNROLL_FACTOR; unroll++) {
            int tile_idx = tile + unroll;
            if (tile_idx < num_tiles) {
                int tile_col = tile_idx * BLOCK_SIZE + threadIdx.x;
                int tile_row = tile_idx * BLOCK_SIZE + threadIdx.y;

                // Load tile of A into shared memory
                if (row < N && tile_col < N) {
                    As[threadIdx.y][threadIdx.x] = A[row * N + tile_col];
                } else {
