import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with register blocking
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define TILE_SIZE 4

__global__ void matrix_multiply_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Each thread computes TILE_SIZE x TILE_SIZE elements
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y * TILE_SIZE;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x * TILE_SIZE;

    // Register accumulation
    float sum[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int tile = 0; tile < N; tile += BLOCK_SIZE) {
        // Load tile of A into shared memory
        int tile_col = tile + threadIdx.x;
        int tile_row = tile + threadIdx.y;

        if (row + threadIdx.y < N && tile_col < N) {
            As[threadIdx.y][threadIdx.x] = A[(row + threadIdx.y) * N + tile_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        if (tile_row < N && col + threadIdx.x < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tile_row * N + (col + threadIdx.x)];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sums
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float a_val = As[threadIdx.y][k];
            float b_val = Bs[k][threadIdx.x];

            #pragma unroll
            for (int i = 0; i < TILE_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < TILE_SIZE; j++) {
                    sum[i][j] += a_val * Bs[k][threadIdx.x + j];
                }
            }
        }

        __syncthreads();
    }

    // Write results
    for (int i = 0; i < TILE_SIZE; i++) {
        for (int j = 0; j < TILE_SIZE; j++) {
            int out_row = row + i;
            int out_col = col + j;
            if (out_row < N && out_col < N) {
                C[out_row * N + out_col] = sum[i][j];
            }
        }
    }
}

torch::Tensor matrix_multiply_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(BLOCK_SIZE / TILE_SIZE, BLOCK_SIZE / TILE_SIZE);
    dim3 numBlocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE, 
                  (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matrix_multiply_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                          B.data_ptr<float>(), 
                                                          C.data_ptr<float>(), 
                                                          N);
    return C;
}
"""

